// Reimplementation of the behavior of whoosh's StandardAnalyzer as used by
// the default TEXT field: RegexTokenizer(r"\w+(\.?\w+)*") | LowercaseFilter
// | StopFilter(STOP_WORDS, minsize=2).

// whoosh.analysis.STOP_WORDS
export const STOP_WORDS = new Set([
  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'but', 'by',
  'for', 'if', 'in', 'into', 'is', 'it',
  'no', 'not', 'of', 'on', 'or', 'such',
  'that', 'the', 'their', 'then', 'there', 'these',
  'they', 'this', 'to', 'was', 'will', 'with',
]);

export const MIN_TOKEN_SIZE = 2;

// Python's \w (unicode word characters) approximated with Unicode property
// escapes; whoosh's default expression is r"\w+(\.?\w+)*".
const TOKEN_RE = /[\p{L}\p{N}_]+(?:\.?[\p{L}\p{N}_]+)*/gu;

// Splits text into analyzed tokens: lowercased, tokens shorter than
// MIN_TOKEN_SIZE dropped, stop words removed.
export function standardTokens(text) {
  const tokens = [];
  for (const match of String(text).matchAll(TOKEN_RE)) {
    const token = match[0].toLowerCase();
    if ([...token].length < MIN_TOKEN_SIZE) continue;
    if (STOP_WORDS.has(token)) continue;
    tokens.push(token);
  }
  return tokens;
}

// Schema and field definitions mirroring:
//   Schema(title=TEXT(stored=True), price=NUMERIC(stored=True), content=TEXT)

import { standardTokens } from './analysis.mjs';

// whoosh NUMERIC defaults to a 32-bit signed integer type.
export const NUMERIC_MIN = -2147483648;
export const NUMERIC_MAX = 2147483647;

export class TextField {
  constructor({ stored = false } = {}) {
    this.kind = 'text';
    this.stored = stored;
  }

  index(value) {
    return standardTokens(value);
  }
}

export class NumericField {
  constructor({ stored = false } = {}) {
    this.kind = 'numeric';
    this.stored = stored;
  }

  index(value) {
    if (value < NUMERIC_MIN || value > NUMERIC_MAX) {
      throw new RangeError(
        `Numeric field value ${value} out of range [${NUMERIC_MIN}, ${NUMERIC_MAX}]`,
      );
    }
    return value;
  }
}

export class Schema {
  constructor() {
    this.fields = {
      title: new TextField({ stored: true }),
      price: new NumericField({ stored: true }),
      content: new TextField({ stored: false }),
    };
  }

  has(name) {
    return Object.prototype.hasOwnProperty.call(this.fields, name);
  }

  get(name) {
    return this.fields[name];
  }

  isNumeric(name) {
    return this.has(name) && this.fields[name].kind === 'numeric';
  }
}

// In-memory index: stores per-field analyzed values and stored field values,
// mirroring the observable behavior of whoosh's create_in/writer/searcher.

export class Index {
  constructor(schema) {
    this.schema = schema;
    this.docs = [];
  }

  // Equivalent of writer.add_document(...): analyzes each field according to
  // the schema. Raises RangeError for out-of-range numeric values, like
  // whoosh's NUMERIC field does on commit-bound writes.
  addDocument(fields) {
    const doc = { analyzed: {}, stored: {} };
    for (const [name, field] of Object.entries(this.schema.fields)) {
      const value = fields[name];
      doc.analyzed[name] = field.index(value);
      if (field.stored) doc.stored[name] = value;
    }
    this.docs.push(doc);
  }

  searcher() {
    return new Searcher(this);
  }
}

export class Searcher {
  constructor(index) {
    this.index = index;
  }

  // Returns the stored fields of matching documents, in index order,
  // truncated to `limit`.
  search(query, limit = 10) {
    const results = [];
    for (const doc of this.index.docs) {
      if (query === null || !query.matches(doc, this.index.schema)) continue;
      results.push(doc.stored);
      if (results.length >= limit) break;
    }
    return results;
  }
}

// Emulates Python's int(str) conversion used by argparse type=int and by
// NUMERIC field query parsing: surrounding whitespace allowed, optional
// sign, digits with single underscores between them (PEP 515).

const INT_RE = /^[+-]?\d(?:_?\d)*$/;

export function parsePythonInt(text) {
  const trimmed = String(text).trim();
  if (!INT_RE.test(trimmed)) return null;
  const value = Number(trimmed.replace(/_/g, ''));
  return Number.isSafeInteger(value) ? value : null;
}

