// Reimplementation of the observable behavior of whoosh's QueryParser
// (default field "title", default OrGroup) as exercised by test15.py:
//   QueryParser("title", ix.schema).parse(args.a)
//
// Supported syntax, matching the probed behavior of the original:
//   - whitespace-separated terms grouped with OR by default
//   - AND / OR / NOT keywords (& and | as standalone tokens), parentheses
//   - field prefixes for known schema fields (title, price, content)
//   - "double quoted" phrases, 'single quoted' plain text
//   - wildcards (* and ?) and fuzzy terms (term~, term~N)
//   - ranges: [a TO b] inclusive, {a TO b} exclusive, mixed brackets
//   - term analysis: lowercased, min length 2, stop words dropped
// The parser is tolerant of malformed input (unbalanced quotes/parens,
// dangling operators), like whoosh's parser.

import { standardTokens } from './analysis.mjs';
import { parsePythonInt } from './pyint.mjs';

// ---------------------------------------------------------------- query nodes

const nodes = {
  term: (field, text) => ({
    matches: (doc) => doc.analyzed[field].includes(text),
  }),
  numTerm: (field, value) => ({
    matches: (doc) => doc.analyzed[field] === value,
  }),
  numAny: (field) => ({
    matches: (doc) => doc.analyzed[field] !== undefined,
  }),
  wildcard: (field, pattern) => {
    const source = pattern
      .split('')
      .map((ch) => {
        if (ch === '*') return '.*';
        if (ch === '?') return '.';
        return ch.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      })
      .join('');
    const re = new RegExp(`^${source}$`, 'u');
    return { matches: (doc) => doc.analyzed[field].some((t) => re.test(t)) };
  },
  fuzzy: (field, base, maxdist) => ({
    matches: (doc) =>
      doc.analyzed[field].some((t) => levenshtein(t, base) <= maxdist),
  }),
  phrase: (field, terms) => ({
    matches: (doc) => {
      const tokens = doc.analyzed[field];
      outer: for (let i = 0; i + terms.length <= tokens.length; i++) {
        for (let j = 0; j < terms.length; j++) {
          if (tokens[i + j] !== terms[j]) continue outer;
        }
        return true;
      }
      return false;
    },
  }),
  textRange: (field, start, end, startExcl, endExcl) => ({
    matches: (doc) =>
      doc.analyzed[field].some(
        (t) =>
          (startExcl ? t > start : t >= start) &&
          (endExcl ? t < end : t <= end),
      ),
  }),
  numRange: (field, start, end, startExcl, endExcl) => ({
    matches: (doc) => {
      const v = doc.analyzed[field];
      return (
        (startExcl ? v > start : v >= start) &&
        (endExcl ? v < end : v <= end)
      );
    },
  }),
  group: (kind, positive, negative) => ({
    matches: (doc, schema) => {
      if (positive.length === 0) return false;
      const hit =
        kind === 'and'
          ? positive.every((q) => q.matches(doc, schema))
          : positive.some((q) => q.matches(doc, schema));
      return hit && !negative.some((q) => q.matches(doc, schema));
    },
  }),
  not: (child) => ({
    matches: (doc, schema) => !child.matches(doc, schema),
  }),
  never: () => ({ matches: () => false }),
};

function levenshtein(a, b) {
  const s = [...a];
  const t = [...b];
  if (Math.abs(s.length - t.length) > 2 && s.length + t.length > 0) {
    // Quick reject only helps performance; compute fully below anyway.
  }
  let prev = Array.from({ length: t.length + 1 }, (_, j) => j);
  for (let i = 1; i <= s.length; i++) {
    const curr = [i];
    for (let j = 1; j <= t.length; j++) {
      curr[j] = Math.min(
        prev[j] + 1,
        curr[j - 1] + 1,
        prev[j - 1] + (s[i - 1] === t[j - 1] ? 0 : 1),
      );
    }
    prev = curr;
  }
  return prev[t.length];
}

// Combines parsed children into a group node; Not children become negative
// clauses. Returns null when nothing usable was parsed.
function makeGroup(kind, children) {
  const positive = [];
  const negative = [];
  for (const child of children) {
    if (child === null) continue;
    if (child._isNot) negative.push(child._isNot);
    else positive.push(child);
  }
  if (positive.length === 0 && negative.length === 0) return null;
  if (positive.length === 1 && negative.length === 0) return positive[0];
  return nodes.group(kind, positive, negative);
}

function makeNot(child) {
  if (child === null) return null;
  return { _isNot: child, matches: (doc, schema) => !child.matches(doc, schema) };
}

// --------------------------------------------------------------------- lexer

const SPECIALS = new Set(['(', ')', '"', "'", '[', ']', '{', '}']);

function lex(text) {
  const tokens = [];
  let i = 0;
  const n = text.length;
  while (i < n) {
    const c = text[i];
    if (/\s/.test(c)) {
      i++;
      continue;
    }
    if (c === '(' || c === ')') {
      tokens.push({ t: c === '(' ? 'lparen' : 'rparen', pos: i, end: i + 1 });
      i++;
      continue;
    }
    if (c === ']' || c === '}') {
      // Stray closer outside a range: ignored.
      i++;
      continue;
    }
    if (c === '"' || c === "'") {
      const start = i;
      i++;
      let buf = '';
      while (i < n && text[i] !== c) buf += text[i++];
      i++; // consume closing quote (or run off the end, tolerated)
      tokens.push({
        t: c === '"' ? 'phrase' : 'squote',
        text: buf,
        pos: start,
        end: i,
      });
      continue;
    }
    if (c === '[' || c === '{') {
      const start = i;
      const open = c;
      i++;
      let buf = '';
      while (i < n && text[i] !== ']' && text[i] !== '}') buf += text[i++];
      const close = i < n ? text[i] : open === '[' ? ']' : '}';
      i++;
      tokens.push({ t: 'range', open, close, text: buf, pos: start, end: i });
      continue;
    }
    const start = i;
    let buf = '';
    while (i < n && !/\s/.test(text[i]) && !SPECIALS.has(text[i])) {
      buf += text[i++];
    }
    tokens.push({ t: 'word', text: buf, pos: start, end: i });
  }
  // Keyword operators are recognized on whole words only.
  for (const tok of tokens) {
    if (tok.t !== 'word') continue;
    if (tok.text === 'AND' || tok.text === '&' || tok.text === '&&') tok.t = 'and';
    else if (tok.text === 'OR' || tok.text === '|' || tok.text === '||') tok.t = 'or';
    else if (tok.text === 'NOT') tok.t = 'not';
  }
  return tokens;
}

