export class QueryParser {
  constructor(fieldname, schema) {
    this.fieldname = fieldname;
    this.schema = schema;
  }

  parse(text) {
    const tokens = lex(String(text));
    this.attachFieldPrefixes(tokens);
    const parser = new Parser(tokens, this.schema, this.fieldname);
    return parser.parseQuery();
  }

  // Merges a "name:" word token directly glued to a phrase, quoted string,
  // range, or group into a field prefix, when the name is a schema field.
  attachFieldPrefixes(tokens) {
    for (let i = 0; i < tokens.length - 1; i++) {
      const tok = tokens[i];
      const next = tokens[i + 1];
      if (tok.t !== 'word' || next.pos !== tok.end) continue;
      const m = /^([\p{L}\p{N}_]+):$/u.exec(tok.text);
      if (!m || !this.schema.has(m[1])) continue;
      if (!['phrase', 'squote', 'range', 'lparen'].includes(next.t)) continue;
      next.field = m[1];
      tokens.splice(i, 1);
      i--;
    }
  }
}

class Parser {
  constructor(tokens, schema, defaultField) {
    this.toks = tokens;
    this.i = 0;
    this.schema = schema;
    this.defaultField = defaultField;
  }

  peek() {
    return this.i < this.toks.length ? this.toks[this.i] : null;
  }

  parseQuery() {
    return this.parseOr(this.defaultField);
  }

  parseOr(fieldCtx) {
    const children = [];
    for (;;) {
      const tk = this.peek();
      if (tk === null || tk.t === 'rparen') break;
      if (tk.t === 'or') {
        this.i++;
        continue;
      }
      const child = this.parseAnd(fieldCtx);
      if (child !== null) children.push(child);
    }
    return makeGroup('or', children);
  }

  parseAnd(fieldCtx) {
    const children = [];
    const first = this.parseUnary(fieldCtx);
    if (first !== null) children.push(first);
    while (this.peek() !== null && this.peek().t === 'and') {
      this.i++;
      const child = this.parseUnary(fieldCtx);
      if (child !== null) children.push(child);
    }
    return makeGroup('and', children);
  }

  parseUnary(fieldCtx) {
    const tk = this.peek();
    if (tk === null) return null;
    if (tk.t === 'not') {
      this.i++;
      return makeNot(this.parseUnary(fieldCtx));
    }
    if (tk.t === 'and' || tk.t === 'or') {
      // Stray leading operator (e.g. "AND ab"): ignored, like whoosh.
      this.i++;
      return this.parseUnary(fieldCtx);
    }
    return this.parseAtom(fieldCtx);
  }

  parseAtom(fieldCtx) {
    const tk = this.peek();
    if (tk === null) return null;
    if (['rparen', 'and', 'or', 'not'].includes(tk.t)) return null;
    this.i++;
    const field = tk.field || fieldCtx;
    switch (tk.t) {
      case 'lparen': {
        const inner = this.parseOr(field);
        if (this.peek() !== null && this.peek().t === 'rparen') this.i++;
        return inner;
      }
      case 'phrase':
        return this.buildPhrase(tk.text, field);
      case 'squote':
        return this.buildAnalyzed(tk.text, field);
      case 'range':
        return this.buildRange(tk, field);
      default:
        return this.buildWord(tk.text, field);
    }
  }

  // A phrase: analyzed tokens must appear consecutively.
  buildPhrase(text, field) {
    if (this.schema.isNumeric(field)) return nodes.never();
    const terms = standardTokens(text);
    if (terms.length === 0) return null;
    if (terms.length === 1) return nodes.term(field, terms[0]);
    return nodes.phrase(field, terms);
  }

  // Single-quoted text: analyzed as a plain word (no wildcard/fuzzy).
  buildAnalyzed(text, field) {
    if (this.schema.isNumeric(field)) {
      const value = parsePythonInt(text);
      return value === null ? nodes.never() : nodes.numTerm(field, value);
    }
    const terms = standardTokens(text);
    if (terms.length === 0) return null;
    if (terms.length === 1) return nodes.term(field, terms[0]);
    return makeGroup(
      'or',
      terms.map((t) => nodes.term(field, t)),
    );
  }

  buildWord(raw, fieldCtx) {
    let text = raw;
    let fuzzyDist = null;
    // Boost suffix is parsed but has no effect on matching.
    const boost = /\^[\d.]+$/.exec(text);
    if (boost) text = text.slice(0, boost.index);
    const fuzzy = /~(\d*(?:\.\d+)?)$/.exec(text);
    if (fuzzy) {
      fuzzyDist = fuzzy[1] === '' ? 1 : Number(fuzzy[1]);
      text = text.slice(0, fuzzy.index);
    }

    let field = fieldCtx;
    let rest = text;
    const fm = /^([\p{L}\p{N}_]+):([\s\S]+)$/u.exec(text);
    if (fm && this.schema.has(fm[1])) {
      field = fm[1];
      rest = fm[2];
    }

    if (this.schema.isNumeric(field)) {
      if (/[*?]/.test(rest)) {
        return rest === '*' ? nodes.numAny(field) : nodes.never();
      }
      if (fuzzyDist !== null) return nodes.never();
      const value = parsePythonInt(rest);
      return value === null ? nodes.never() : nodes.numTerm(field, value);
    }

    if (fuzzyDist !== null) {
      return nodes.fuzzy(field, rest.toLowerCase(), fuzzyDist);
    }
    if (/[*?]/.test(rest)) {
      return nodes.wildcard(field, rest.toLowerCase());
    }
    return this.buildAnalyzed(rest, field);
  }

  buildRange(tk, field) {
    const parts = tk.text.split(/\s+TO\s+/);
    if (parts.length !== 2 || parts[0].trim() === '' || parts[1].trim() === '') {
      // Not a range after all (e.g. "[ab to cd]"): treat as plain text.
      return this.buildAnalyzed(tk.text, field);
    }
    const startExcl = tk.open === '{';
    const endExcl = tk.close === '}';
    if (this.schema.isNumeric(field)) {
      const start = parsePythonInt(parts[0].trim());
      const end = parsePythonInt(parts[1].trim());
      if (start === null || end === null) return nodes.never();
      return nodes.numRange(field, start, end, startExcl, endExcl);
    }
    return nodes.textRange(
      field,
      parts[0].trim().toLowerCase(),
      parts[1].trim().toLowerCase(),
      startExcl,
      endExcl,
    );
  }
}

// Minimal reimplementation of Python's argparse behavior for this script:
//   parser.add_argument('--a', type=str, required=True)
//   parser.add_argument('--b', type=int, required=True)
//   parser.add_argument('--c', type=int, required=True)
// Replicates: --opt value and --opt=value forms, unambiguous prefix
// abbreviation, negative-number values, last-wins repetition, "--"
// separator, and argparse's error messages/exit codes.

import { parsePythonInt } from './pyint.mjs';

const LONG_OPTIONS = ['--help', '--a', '--b', '--c'];
const VALUE_OPTIONS = new Set(['--a', '--b', '--c']);
// argparse's _negative_number_matcher
const NEGATIVE_NUMBER_RE = /^-\d+$|^-\d*\.\d+$/;

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B --c C`;
}

function fail(prog, message) {
  process.stderr.write(`${usageLine(prog)}\n`);
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

function printHelp(prog) {
  process.stdout.write(
    `${usageLine(prog)}\n` +
      `\n` +
      `options:\n` +
      `  -h, --help  show this help message and exit\n` +
      `  --a A\n` +
      `  --b B\n` +
      `  --c C\n`,
  );
  process.exit(0);
}

// An argument string is option-like when it starts with '-', is not just
// '-', is not a negative number, and contains no space (argparse rules for
// a parser whose options do not look like negative numbers).
function looksLikeOption(text) {
  return (
    text.length > 1 &&
    text[0] === '-' &&
    !NEGATIVE_NUMBER_RE.test(text) &&
    !text.includes(' ')
  );
}

function resolveLongOption(prog, name) {
  if (LONG_OPTIONS.includes(name)) return name;
  const candidates = LONG_OPTIONS.filter((opt) => opt.startsWith(name));
  if (candidates.length === 1) return candidates[0];
  if (candidates.length > 1) {
    fail(prog, `ambiguous option: ${name} could match ${candidates.join(', ')}`);
  }
  return null;
}

export function parseArgs(argv, prog) {
  const values = {};
  const extras = [];
  let i = 0;
  let sawDoubleDash = false;

  while (i < argv.length) {
    const token = argv[i];
    i++;

    if (sawDoubleDash) {
      extras.push(token);
      continue;
    }
    if (token === '--') {
      sawDoubleDash = true;
      continue;
    }
    if (token === '-h') {
      printHelp(prog);
    }
    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      const name = eq === -1 ? token : token.slice(0, eq);
      const inlineValue = eq === -1 ? null : token.slice(eq + 1);
      const resolved = resolveLongOption(prog, name);
      if (resolved === null) {
        extras.push(token);
        continue;
      }
      if (resolved === '--help') {
        printHelp(prog);
      }
      let value = inlineValue;
      if (value === null) {
        if (i >= argv.length || looksLikeOption(argv[i])) {
          fail(prog, `argument ${resolved}: expected one argument`);
        }
        value = argv[i];
        i++;
      }
      if (resolved === '--a') {
        values.a = value;
      } else {
        const parsed = parsePythonInt(value);
        if (parsed === null) {
          fail(prog, `argument ${resolved}: invalid int value: '${value}'`);
        }
        values[resolved === '--b' ? 'b' : 'c'] = parsed;
      }
      continue;
    }
    if (looksLikeOption(token)) {
      // Unknown short option.
      extras.push(token);
      continue;
    }
    // Positional (or bare "-", or a negative number): not expected here.
    extras.push(token);
  }

  const missing = [];
  if (!('a' in values)) missing.push('--a');
  if (!('b' in values)) missing.push('--b');
  if (!('c' in values)) missing.push('--c');
  if (missing.length > 0) {
    fail(prog, `the following arguments are required: ${missing.join(', ')}`);
  }
  if (extras.length > 0) {
    fail(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return values;
}

// Node.js (ESM) port of /workspace/dataset/test15.py.
// Mirrors:
//   schema = Schema(title=TEXT(stored=True), price=NUMERIC(stored=True), content=TEXT)
//   two documents (price b / c, content item1 / item2, title = args.a)
//   QueryParser("title", ix.schema).parse(args.a), search(limit=10)
//   print(sum(r["price"] for r in results))

import { basename } from 'node:path';
import { parseArgs } from './lib/argparse.mjs';
import { Schema } from './lib/schema.mjs';
import { Index } from './lib/index.mjs';
import { QueryParser } from './lib/qparser.mjs';

const prog = basename(process.argv[1] || 'test15.mjs');
const args = parseArgs(process.argv.slice(2), prog);

const schema = new Schema();
const ix = new Index(schema);

try {
  ix.addDocument({ title: args.a, price: args.b, content: 'item1' });
  ix.addDocument({ title: args.a, price: args.c, content: 'item2' });
} catch (err) {
  if (err instanceof RangeError) {
    // whoosh raises ValueError for out-of-range NUMERIC values; the original
    // script crashes with a traceback and exits non-zero, printing nothing.
    process.stderr.write(`ValueError: ${err.message}\n`);
    process.exit(1);
  }
  throw err;
}

const searcher = ix.searcher();
const query = new QueryParser('title', schema).parse(args.a);
const results = searcher.search(query, 10);

let totalPrice = 0;
for (const result of results) {
  totalPrice += result.price;
}
console.log(totalPrice);

